func TestStripGitEnv(t *testing.T) {
	t.Parallel()

	env := []string{
		"HOME=/Users/test",
		"GIT_DIR=/repo/.git",
		"PATH=/usr/bin",
		"GIT_WORK_TREE=/repo",
		"GIT_INDEX_FILE=/repo/.git/index",
		"SHELL=/bin/zsh",
		"CLAUDECODE=1",
	}

	filtered := StripGitEnv(env)

	expected := []string{
