  1→// Package summarize provides AI-powered summarization of development sessions.
  2→package summarize
  3→
  4→import (
  5→	"context"
  6→	"encoding/json"
  7→	"errors"
  8→	"fmt"
  9→	"strings"
 10→
 11→	"github.com/entireio/cli/cmd/entire/cli/agent"
 12→	"github.com/entireio/cli/cmd/entire/cli/agent/geminicli"
 13→	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
 14→	"github.com/entireio/cli/cmd/entire/cli/settings"
 15→	"github.com/entireio/cli/cmd/entire/cli/transcript"
 16→)
 17→
 18→// GenerateFromTranscript generates a summary from raw transcript bytes.
 19→// This is the shared implementation used by both explain --generate and auto-summarize.
 20→//
 21→// Parameters:
 22→//   - ctx: context for cancellation
 23→//   - transcriptBytes: raw transcript bytes (JSONL or JSON format depending on agent)
 24→//   - filesTouched: list of files modified during the session
 25→//   - agentType: the agent type to determine transcript format
 26→//   - generator: summary generator to use (if nil, resolves from settings)
 27→//
 28→// Returns nil, error if transcript is empty or cannot be parsed.
 29→func GenerateFromTranscript(ctx context.Context, transcriptBytes []byte, filesTouched []string, agentType agent.AgentType, generator Generator) (*checkpoint.Summary, error) {
 30→	if len(transcriptBytes) == 0 {
 31→		return nil, errors.New("empty transcript")
 32→	}
 33→
 34→	// Build condensed transcript for summarization
 35→	condensed, err := BuildCondensedTranscriptFromBytes(transcriptBytes, agentType)
 36→	if err != nil {
 37→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
 38→	}
 39→	if len(condensed) == 0 {
 40→		return nil, errors.New("transcript has no content to summarize")
 41→	}
 42→
 43→	input := Input{
 44→		Transcript:   condensed,
 45→		FilesTouched: filesTouched,
 46→	}
 47→
 48→	// Use default generator if none provided
 49→	if generator == nil {
 50→		generator = defaultGenerator()
 51→	}
 52→
 53→	summary, err := generator.Generate(ctx, input)
 54→	if err != nil {
 55→		return nil, fmt.Errorf("failed to generate summary: %w", err)
 56→	}
 57→
 58→	return summary, nil
 59→}
 60→
 61→// defaultGenerator creates a Generator based on settings.
 62→// If the configured agent supports the Prompter interface, uses PrompterGenerator.
 63→// Falls back to ClaudeGenerator for backward compatibility.
 64→//
 65→//nolint:ireturn // factory function intentionally returns Generator interface
 66→func defaultGenerator() Generator {
 67→	s, err := settings.Load()
 68→	if err != nil {
 69→		return &ClaudeGenerator{}
 70→	}
 71→
 72→	agentName := agent.AgentName(s.SummarizeAgent())
 73→	if agentName == "" {
 74→		agentName = agent.DefaultAgentName
 75→	}
 76→
 77→	ag, err := agent.Get(agentName)
 78→	if err != nil {
 79→		return &ClaudeGenerator{}
 80→	}
 81→
 82→	prompter, ok := ag.(agent.Prompter)
 83→	if !ok {
 84→		// Agent doesn't support Prompter, fall back to ClaudeGenerator
 85→		return &ClaudeGenerator{}
 86→	}
 87→
 88→	return &PrompterGenerator{
 89→		Prompter: prompter,
 90→		Model:    s.SummarizeModel(),
 91→	}
 92→}
 93→
 94→// Generator generates checkpoint summaries using an LLM.
 95→type Generator interface {
 96→	// Generate creates a summary from checkpoint data.
 97→	// Returns the generated summary or an error if generation fails.
 98→	Generate(ctx context.Context, input Input) (*checkpoint.Summary, error)
 99→}
100→
101→// Input contains condensed checkpoint data for summarization.
102→type Input struct {
103→	// Transcript is the condensed transcript entries
104→	Transcript []Entry
105→
106→	// FilesTouched are the files modified during the session
107→	FilesTouched []string
108→}
109→
110→// EntryType represents the type of a transcript entry.
111→type EntryType string
112→
113→const (
114→	// EntryTypeUser indicates a user prompt entry.
115→	EntryTypeUser EntryType = "user"
116→	// EntryTypeAssistant indicates an assistant response entry.
117→	EntryTypeAssistant EntryType = "assistant"
118→	// EntryTypeTool indicates a tool call entry.
119→	EntryTypeTool EntryType = "tool"
120→)
121→
122→// Entry represents one item in the condensed transcript.
123→type Entry struct {
124→	// Type is the entry type (user, assistant, tool)
125→	Type EntryType
126→
127→	// Content is the text content for user/assistant entries
128→	Content string
129→
130→	// ToolName is the name of the tool (for tool entries)
131→	ToolName string
132→
133→	// ToolDetail is a description or file path (for tool entries)
134→	ToolDetail string
135→}
136→
137→// minimalDetailTools lists tools that should show only essential details in summaries.
138→// These tools often have verbose outputs that don't add value to summarization.
139→// The detail shown is typically just a path, URL, or identifier rather than full content.
140→var minimalDetailTools = map[string]bool{
141→	"Skill":    true, // Show skill name only, not loaded content
142→	"Read":     true, // Show file path only, not file contents
143→	"WebFetch": true, // Show URL only, not fetched content
144→}
145→
146→// BuildCondensedTranscriptFromBytes parses transcript bytes and extracts a condensed view.
147→// This is a convenience function that combines parsing and condensing.
148→// The agentType parameter determines which parser to use (Claude JSONL vs Gemini JSON).
149→func BuildCondensedTranscriptFromBytes(content []byte, agentType agent.AgentType) ([]Entry, error) {
150→	switch agentType {
151→	case agent.AgentTypeGemini:
152→		return buildCondensedTranscriptFromGemini(content)
153→	case agent.AgentTypeClaudeCode, agent.AgentTypeUnknown:
154→		// Claude format - fall through to shared logic below
155→	}
156→	// Claude format (JSONL) - handles Claude Code, Unknown, and any future agent types
157→	lines, err := transcript.ParseFromBytes(content)
158→	if err != nil {
159→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
160→	}
161→	return BuildCondensedTranscript(lines), nil
162→}
163→
164→// buildCondensedTranscriptFromGemini parses Gemini JSON transcript and extracts a condensed view.
165→func buildCondensedTranscriptFromGemini(content []byte) ([]Entry, error) {
166→	geminiTranscript, err := geminicli.ParseTranscript(content)
167→	if err != nil {
168→		return nil, fmt.Errorf("failed to parse Gemini transcript: %w", err)
169→	}
170→
171→	var entries []Entry
172→	for _, msg := range geminiTranscript.Messages {
173→		switch msg.Type {
174→		case geminicli.MessageTypeUser:
175→			if msg.Content != "" {
176→				entries = append(entries, Entry{
177→					Type:    EntryTypeUser,
178→					Content: msg.Content,
179→				})
180→			}
181→		case geminicli.MessageTypeGemini:
182→			// Add assistant content
183→			if msg.Content != "" {
184→				entries = append(entries, Entry{
185→					Type:    EntryTypeAssistant,
186→					Content: msg.Content,
187→				})
188→			}
189→			// Add tool calls
190→			for _, tc := range msg.ToolCalls {
191→				entries = append(entries, Entry{
192→					Type:       EntryTypeTool,
193→					ToolName:   tc.Name,
194→					ToolDetail: extractGeminiToolDetail(tc.Args),
195→				})
196→			}
197→		}
198→	}
199→
200→	return entries, nil
201→}
202→
203→// extractGeminiToolDetail extracts an appropriate detail string from Gemini tool args.
204→func extractGeminiToolDetail(args map[string]interface{}) string {
205→	// Check common fields in order of preference
206→	for _, key := range []string{"description", "command", "file_path", "path", "pattern"} {
207→		if v, ok := args[key].(string); ok && v != "" {
208→			return v
209→		}
210→	}
211→	return ""
212→}
213→
214→// BuildCondensedTranscript extracts a condensed view of the transcript.
215→// It processes user prompts, assistant responses, and tool calls into
216→// a simplified format suitable for LLM summarization.
217→func BuildCondensedTranscript(lines []transcript.Line) []Entry {
218→	var entries []Entry
219→
220→	for _, line := range lines {
221→		switch line.Type {
222→		case transcript.TypeUser:
223→			if entry := extractUserEntry(line); entry != nil {
224→				entries = append(entries, *entry)
225→			}
226→		case transcript.TypeAssistant:
227→			assistantEntries := extractAssistantEntries(line)
228→			entries = append(entries, assistantEntries...)
229→		}
230→	}
231→
232→	return entries
233→}
234→
235→// skillContentPrefix identifies user messages that are skill content injections.
236→// These are injected after a Skill tool call and contain the full skill instructions.
237→const skillContentPrefix = "Base directory for this skill:"
238→
239→// extractUserEntry extracts a user entry from a transcript line.
240→// Returns nil if the line doesn't contain a valid user prompt or is skill content.
241→func extractUserEntry(line transcript.Line) *Entry {
242→	content := transcript.ExtractUserContent(line.Message)
243→	if content == "" {
244→		return nil
245→	}
246→
247→	// Skip skill content injections - these are verbose skill instructions
248→	// injected as user messages after Skill tool invocations in Claude Code.
249→	// The prefix "Base directory for this skill:" is added by the superpowers
250→	// plugin when loading skill content. This filtering reduces transcript noise
251→	// since skill content is documentation, not user intent.
252→	if strings.HasPrefix(content, skillContentPrefix) {
253→		return nil
254→	}
255→
256→	return &Entry{
257→		Type:    EntryTypeUser,
258→		Content: content,
259→	}
260→}
261→
262→// extractAssistantEntries extracts assistant and tool entries from a transcript line.
263→func extractAssistantEntries(line transcript.Line) []Entry {
264→	var msg transcript.AssistantMessage
265→	if err := json.Unmarshal(line.Message, &msg); err != nil {
266→		return nil
267→	}
268→
269→	var entries []Entry
270→
271→	for _, block := range msg.Content {
272→		switch block.Type {
273→		case transcript.ContentTypeText:
274→			if block.Text != "" {
275→				entries = append(entries, Entry{
276→					Type:    EntryTypeAssistant,
277→					Content: block.Text,
278→				})
279→			}
280→		case transcript.ContentTypeToolUse:
281→			var input transcript.ToolInput
282→			_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing
283→
284→			detail := extractToolDetail(block.Name, input)
285→
286→			entries = append(entries, Entry{
287→				Type:       EntryTypeTool,
288→				ToolName:   block.Name,
289→				ToolDetail: detail,
290→			})
291→		}
292→	}
293→
294→	return entries
295→}
296→
297→// extractToolDetail extracts an appropriate detail string for a tool call.
298→// For tools in minimalDetailTools, only essential identifiers are shown.
299→// For other tools, the full detail chain is used.
300→func extractToolDetail(toolName string, input transcript.ToolInput) string {
301→	// For minimal detail tools, extract only the essential identifier
302→	if minimalDetailTools[toolName] {
303→		switch toolName {
304→		case "Skill":
305→			return input.Skill
306→		case "Read":
307→			if input.FilePath != "" {
308→				return input.FilePath
309→			}
310→			return input.NotebookPath
311→		case "WebFetch":
312→			return input.URL
313→		}
314→	}
315→
316→	// For other tools, use the full detail chain
317→	if input.Description != "" {
318→		return input.Description
319→	}
320→	if input.Command != "" {
321→		return input.Command
322→	}
323→	if input.FilePath != "" {
324→		return input.FilePath
325→	}
326→	if input.NotebookPath != "" {
327→		return input.NotebookPath
328→	}
329→	return input.Pattern
330→}
331→
332→// FormatCondensedTranscript formats an Input into a human-readable string for LLM.
333→// The format is:
334→//
335→//	[User] user prompt here
336→//
337→//	[Assistant] assistant response here
338→//
339→//	[Tool] ToolName: description or file path
340→func FormatCondensedTranscript(input Input) string {
341→	var sb strings.Builder
342→
343→	for i, entry := range input.Transcript {
344→		if i > 0 {
345→			sb.WriteString("\n")
346→		}
347→
348→		switch entry.Type {
349→		case EntryTypeUser:
350→			sb.WriteString("[User] ")
351→			sb.WriteString(entry.Content)
352→			sb.WriteString("\n")
353→		case EntryTypeAssistant:
354→			sb.WriteString("[Assistant] ")
355→			sb.WriteString(entry.Content)
356→			sb.WriteString("\n")
357→		case EntryTypeTool:
358→			sb.WriteString("[Tool] ")
359→			sb.WriteString(entry.ToolName)
360→			if entry.ToolDetail != "" {
361→				sb.WriteString(": ")
362→				sb.WriteString(entry.ToolDetail)
363→			}
364→			sb.WriteString("\n")
365→		}
366→	}
367→
368→	if len(input.FilesTouched) > 0 {
369→		sb.WriteString("\n[Files Modified]\n")
370→		for _, file := range input.FilesTouched {
371→			fmt.Fprintf(&sb, "- %s\n", file)
372→		}
373→	}
374→
375→	return sb.String()
376→}
