 59→	// This is needed because the CLI may be run from a subdirectory
 60→	repoRoot, err := paths.RepoRoot()
 61→	if err != nil {
 62→		// Not in a git repo, fall back to CWD-relative check
 63→		repoRoot = "."
 64→	}
 65→
 66→	// Check for .claude directory
 67→	claudeDir := filepath.Join(repoRoot, ".claude")
 68→	if _, err := os.Stat(claudeDir); err == nil {
