 89→// ParseHookInput parses Claude Code hook input from stdin.
 90→func (c *ClaudeCodeAgent) ParseHookInput(hookType agent.HookType, reader io.Reader) (*agent.HookInput, error) {
 91→	data, err := io.ReadAll(reader)
 92→	if err != nil {
 93→		return nil, fmt.Errorf("failed to read input: %w", err)
 94→	}
 95→
 96→	if len(data) == 0 {
 97→		return nil, errors.New("empty input")
 98→	}
 99→
100→	input := &agent.HookInput{
101→		HookType:  hookType,
102→		Timestamp: time.Now(),
103→		RawData:   make(map[string]interface{}),
104→	}
105→
106→	// Parse based on hook type
107→	switch hookType {
108→	case agent.HookUserPromptSubmit:
109→		var raw userPromptSubmitRaw
110→		if err := json.Unmarshal(data, &raw); err != nil {
111→			return nil, fmt.Errorf("failed to parse user prompt submit: %w", err)
112→		}
113→		input.SessionID = raw.SessionID
114→		input.SessionRef = raw.TranscriptPath
115→		input.UserPrompt = raw.Prompt
116→
117→	case agent.HookSessionStart, agent.HookSessionEnd, agent.HookStop:
118→		var raw sessionInfoRaw
119→		if err := json.Unmarshal(data, &raw); err != nil {
120→			return nil, fmt.Errorf("failed to parse session info: %w", err)
121→		}
122→		input.SessionID = raw.SessionID
123→		input.SessionRef = raw.TranscriptPath
124→
125→	case agent.HookPreToolUse:
126→		var raw taskHookInputRaw
127→		if err := json.Unmarshal(data, &raw); err != nil {
128→			return nil, fmt.Errorf("failed to parse pre-tool input: %w", err)
129→		}
130→		input.SessionID = raw.SessionID
131→		input.SessionRef = raw.TranscriptPath
132→		input.ToolUseID = raw.ToolUseID
133→		input.ToolInput = raw.ToolInput
134→
135→	case agent.HookPostToolUse:
136→		var raw postToolHookInputRaw
137→		if err := json.Unmarshal(data, &raw); err != nil {
138→			return nil, fmt.Errorf("failed to parse post-tool input: %w", err)
139→		}
140→		input.SessionID = raw.SessionID
141→		input.SessionRef = raw.TranscriptPath
142→		input.ToolUseID = raw.ToolUseID
143→		input.ToolInput = raw.ToolInput
144→		// Store agent ID in raw data for Task tool results
145→		if raw.ToolResponse.AgentID != "" {
146→			input.RawData["agent_id"] = raw.ToolResponse.AgentID
147→		}
148→	}
149→
150→	return input, nil
151→}
