183→// ReadSession reads a session from Claude's storage (JSONL transcript file).
184→// The session data is stored in NativeData as raw JSONL bytes.
185→// ModifiedFiles is computed by parsing the transcript.
186→func (c *ClaudeCodeAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
187→	if input.SessionRef == "" {
188→		return nil, errors.New("session reference (transcript path) is required")
189→	}
190→
191→	// Read the raw JSONL file
192→	data, err := os.ReadFile(input.SessionRef)
193→	if err != nil {
194→		return nil, fmt.Errorf("failed to read transcript: %w", err)
195→	}
196→
197→	// Parse to extract computed fields
198→	lines, err := transcript.ParseFromBytes(data)
199→	if err != nil {
200→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
201→	}
202→
203→	return &agent.AgentSession{
204→		SessionID:     input.SessionID,
205→		AgentName:     c.Name(),
206→		SessionRef:    input.SessionRef,
207→		StartTime:     time.Now(),
208→		NativeData:    data,
209→		ModifiedFiles: ExtractModifiedFiles(lines),
210→	}, nil
211→}
212→
213→// WriteSession writes a session to Claude's storage (JSONL transcript file).
214→// Uses the NativeData field which contains raw JSONL bytes.
215→// The session must have been created by Claude Code (AgentName check).
216→func (c *ClaudeCodeAgent) WriteSession(session *agent.AgentSession) error {
217→	if session == nil {
218→		return errors.New("session is nil")
219→	}
220→
221→	// Verify this session belongs to Claude Code
222→	if session.AgentName != "" && session.AgentName != c.Name() {
223→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
224→	}
225→
226→	if session.SessionRef == "" {
227→		return errors.New("session reference (transcript path) is required")
228→	}
229→
230→	if len(session.NativeData) == 0 {
231→		return errors.New("session has no native data to write")
232→	}
233→
234→	// Write the raw JSONL data
235→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
236→		return fmt.Errorf("failed to write transcript: %w", err)
237→	}
238→
239→	return nil
240→}
