264→// TruncateAtUUID returns a new session truncated at the given UUID (inclusive).
265→// This is used for rewind operations to restore transcript state.
266→// Requires NativeData to be populated.
267→func (c *ClaudeCodeAgent) TruncateAtUUID(session *agent.AgentSession, uuid string) (*agent.AgentSession, error) {
268→	if session == nil {
269→		return nil, errors.New("session is nil")
270→	}
271→
272→	if len(session.NativeData) == 0 {
273→		return nil, errors.New("session has no native data")
274→	}
275→
276→	if uuid == "" {
277→		// No truncation needed, return copy
278→		return &agent.AgentSession{
279→			SessionID:     session.SessionID,
280→			AgentName:     session.AgentName,
281→			RepoPath:      session.RepoPath,
282→			SessionRef:    session.SessionRef,
283→			StartTime:     session.StartTime,
284→			NativeData:    session.NativeData,
285→			ModifiedFiles: session.ModifiedFiles,
286→		}, nil
287→	}
288→
289→	// Parse, truncate, re-serialize
290→	lines, err := transcript.ParseFromBytes(session.NativeData)
291→	if err != nil {
292→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
293→	}
294→
295→	truncated := TruncateAtUUID(lines, uuid)
296→
297→	newData, err := SerializeTranscript(truncated)
298→	if err != nil {
299→		return nil, fmt.Errorf("failed to serialize truncated transcript: %w", err)
300→	}
301→
302→	return &agent.AgentSession{
303→		SessionID:     session.SessionID,
304→		AgentName:     session.AgentName,
305→		RepoPath:      session.RepoPath,
306→		SessionRef:    session.SessionRef,
307→		StartTime:     session.StartTime,
308→		NativeData:    newData,
309→		ModifiedFiles: ExtractModifiedFiles(truncated),
310→	}, nil
311→}
